 use RefreshDatabase;
 public function test_rejected_text_retains_response_for_local_diagnosis_without_another_paid_call(){[$u,$p]=$this->source();$raw=json_encode(['angle'=>'Lamp campaign','headline'=>'Hello','cta'=>'Explore','variants'=>['facebook'=>'Wrong product'],'slides'=>[['headline'=>'Hello','prompt'=>'Lamp']]]);Http::fake(['api.openai.com/v1/responses'=>Http::response(['status'=>'completed','output'=>[['content'=>[['type'=>'output_text','text'=>$raw]]]]])]);$s=app(MarketingFreePosts::class);$r=$s->prepare($u,$this->brief($p));$r=$s->step($u,$r->id);$this->assertSame('text_unknown',$r->status);$this->assertSame($raw,$r->snapshot['text_result']['raw']);$this->assertNotEmpty($r->snapshot['validation_error']);$s->step($u,$r->id);Http::assertSentCount(1);}
 public function test_legacy_prepared_request_digest_remains_idempotent(){[$u,$p]=$this->source();$v=$this->brief($p);$s=app(MarketingFreePosts::class);$r=$s->prepare($u,$v);$snapshot=$r->snapshot;$snapshot['input_digest']=hash('sha256',json_encode($v+['product_ids'=>[$p->id]]));$r->update(['snapshot'=>$snapshot]);$this->assertSame($r->id,$s->prepare($u,$v)->id);Http::assertNothingSent();}
 public function test_failed_image_storage_never_advances_or_spends_on_another_slide(){[$u,$p]=$this->source();$this->fake(3);$s=app(MarketingFreePosts::class);$r=$s->prepare($u,$this->brief($p,['type'=>'carousel']));$s->step($u,$r->id);$public=Storage::disk('public');$disk=\Mockery::mock(\Illuminate\Filesystem\FilesystemAdapter::class);$disk->shouldReceive('put')->once()->andReturn(false);Storage::shouldReceive('disk')->with('local')->andReturn($disk);Storage::shouldReceive('disk')->with('public')->andReturn($public);$r=$s->step($u,$r->id);$this->assertSame('image_unknown',$r->status);$this->assertCount(0,$r->snapshot['images']);$this->assertArrayHasKey('image_1',$r->receipts);$s->step($u,$r->id);Http::assertSentCount(2);$this->assertDatabaseCount('marketing_posts',0);}
 public function test_production_free_posts_require_dedicated_enablement_without_global_execution(){[$u,$p]=$this->source();app()->instance('env','production');config(['marketing.free_post_generation_enabled'=>false,'marketing.execution_enabled'=>false]);$this->getJson('/admin/marketing/ai-posts')->assertForbidden();config(['marketing.free_post_generation_enabled'=>true]);$this->get('/admin/marketing/ai-posts')->assertOk();$this->withSession(['_token'=>'release-test-token'])->withHeader('X-CSRF-TOKEN','release-test-token')->postJson('/admin/marketing/free-posts',$this->brief($p))->assertOk()->assertJsonPath('status','free_prepared');Http::assertNothingSent();}
 public function test_ai_selects_image_count_for_multiple_mode_and_saves_matching_carousels(){[$u,$p]=$this->source();$this->fake(4);$s=app(MarketingFreePosts::class);$r=$s->prepare($u,$this->brief($p,['type'=>'promotion','image_mode'=>'multiple']));$this->assertNull($r->snapshot['facts']['slide_count']);$r=$s->step($u,$r->id);$this->assertSame('free_text_completed',$r->status);$this->assertSame(4,$r->snapshot['facts']['slide_count']);for($i=0;$i<6;$i++)$r=$s->step($u,$r->id);$this->assertSame('completed',$r->status);foreach($r->post_ids as $id){$doc=MarketingPost::findOrFail($id)->document;$this->assertSame('carousel',$doc['format']);$this->assertCount(4,$doc['assets']);$this->assertSame('A calmer workspace',$doc['title']);}Http::assertSentCount(5);}
 public function test_single_image_mode_overrides_carousel_type_and_rejects_wrong_model_count(){[$u,$p]=$this->source();$this->fake(3);$s=app(MarketingFreePosts::class);$r=$s->prepare($u,$this->brief($p,['type'=>'carousel','image_mode'=>'single']));$this->assertSame(1,$r->snapshot['facts']['slide_count']);$r=$s->step($u,$r->id);$this->assertSame('text_unknown',$r->status);$s->step($u,$r->id);Http::assertSentCount(1);}
 public function test_multiple_mode_rejects_one_or_eleven_images_before_image_generation(){[$u,$p]=$this->source();$s=app(MarketingFreePosts::class);$method=new \ReflectionMethod($s,'validatePlan');foreach([1,11] as $n){$plan=['angle'=>'Desk setup','headline'=>'Focus','cta'=>'Explore','variants'=>['facebook'=>'Desk Lamp'],'slides'=>array_fill(0,$n,['headline'=>'Focus','prompt'=>'Verified lamp'])];try{$method->invoke($s,$plan,['title'=>$p->title,'platforms'=>['facebook'],'slide_count'=>null]);$this->fail('Unsupported image count accepted');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertSame(422,$e->getStatusCode());}}Http::assertNothingSent();}
 public function test_promotion_universal_reference_is_verified_and_keeps_style_out_of_product_claims(){[$u,$p]=$this->source();$r=app(MarketingFreePosts::class)->prepare($u,$this->brief($p,['type'=>'promotion','reference'=>'promotion-neon-flash','notes'=>'Christmas 20% OFF']));$this->assertSame('universal',$r->snapshot['reference']['scope']);$this->assertSame('Neon flash',$r->snapshot['facts']['reference']['style']);$this->assertSame(['20'],$r->snapshot['facts']['authorized_percentages']);$this->assertSame($p->title,$r->snapshot['facts']['title']);$this->assertCount(1,$r->snapshot['reference']['paths']);Http::assertNothingSent();}
 public function test_promotion_uses_single_image_user_offer_and_poster_aesthetics(){[$u,$p]=$this->source();$s=app(MarketingFreePosts::class);$r=$s->prepare($u,$this->brief($p,['type'=>'promotion','notes'=>'Christmas Sale 30% OFF','reference'=>'poster-technology-electronic']));$this->assertSame('promotion',$r->snapshot['facts']['type']);$this->assertSame(1,$r->snapshot['facts']['slide_count']);$this->assertSame(['30'],$r->snapshot['facts']['authorized_percentages']);$this->assertStringContainsString('Promotion',$r->snapshot['facts']['caption_strategy']);$this->assertCount(1,$r->snapshot['reference']['paths']);Http::assertNothingSent();}
 public function test_product_search_is_lazy_bounded_and_can_restore_only_selected_products(){
  [$u,$p]=$this->source();\Illuminate\Support\Facades\DB::enableQueryLog();$this->get('/admin/marketing/ai-posts')->assertOk()->assertSee('"products":[]',false);$queries=\Illuminate\Support\Facades\DB::getQueryLog();$this->assertFalse(collect($queries)->contains(fn($q)=>preg_match('/from ["`]?products["`]?/i',$q['query'])===1));
  $this->getJson('/admin/marketing/free-post-products')->assertOk()->assertJsonPath('products',[]);
  $this->getJson('/admin/marketing/free-post-products?q=Desk')->assertOk()->assertJsonPath('products.0.id',$p->id);
  $this->getJson('/admin/marketing/free-post-products?q=NotFound')->assertOk()->assertJsonPath('products',[]);
  $this->getJson('/admin/marketing/free-post-products?ids[]='.$p->id)->assertOk()->assertJsonPath('products.0.id',$p->id);
  $this->getJson('/admin/marketing/free-post-products?q=%25')->assertOk()->assertJsonPath('products',[]);Http::assertNothingSent();
 }
 public function test_product_search_limits_matches_and_enforces_marketing_access(){[$u,$p]=$this->source();for($i=0;$i<22;$i++){$q=$p->replicate();$q->title='Desk Lamp '.$i;$q->handle='lamp-'.$i;$q->save();$q->images()->create(['path'=>'products/lamp.png','position'=>0]);}$this->getJson('/admin/marketing/free-post-products?q=Desk')->assertOk()->assertJsonCount(20,'products')->assertJsonPath('more',true);$this->actingAs(User::factory()->create());$this->getJson('/admin/marketing/free-post-products?q=Desk')->assertUnauthorized();Http::assertNothingSent();}
 public function test_multi_product_brief_preserves_all_sources_and_custom_cta_and_offer(){
  [$u,$p]=$this->source();$q=$p->replicate();$q->title='Office Chair';$q->handle='office-chair';$q->save();$q->images()->create(['path'=>'products/lamp.png','position'=>0]);
  $s=app(MarketingFreePosts::class);$r=$s->prepare($u,$this->brief($p,['product_ids'=>[$p->id,$q->id],'notes'=>'Christmas Sale 30% OFF selected products','cta_url'=>'https://shop.example/christmas?campaign=x']));
  $this->assertCount(2,$r->snapshot['products']);$this->assertSame([$p->id,$q->id],$r->snapshot['product_ids']);$this->assertSame('Office Chair',$r->snapshot['facts']['products'][1]['title']);$this->assertSame('https://shop.example/christmas?campaign=x',$r->snapshot['facts']['cta_destination']);
  $plan=['angle'=>'Christmas choices','headline'=>'Christmas 30% OFF','cta'=>'Explore Christmas','variants'=>array_fill_keys(['facebook','instagram','tiktok'],"Desk Lamp and Office Chair.\n\nChristmas Sale 30% OFF."),'slides'=>[['headline'=>'Christmas 30% OFF','prompt'=>'Desk Lamp and Office Chair Christmas 30% OFF, no invented prices.']]];
  Http::fake(['api.openai.com/v1/responses'=>Http::response(['status'=>'completed','output'=>[['content'=>[['type'=>'output_text','text'=>json_encode($plan)]]]]])]);$r=$s->step($u,$r->id);$this->assertSame('free_text_completed',$r->status);foreach($r->creative['variants'] as $copy)$this->assertStringContainsString('https://shop.example/christmas?campaign=x',$copy);
  $q->update(['title'=>'Changed Chair']);$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpException::class);$s->step($u,$r->id);
 }
 public function test_multi_product_rejects_unsafe_cta_before_provider_calls(){[$u,$p]=$this->source();foreach(['javascript:alert(1)','https://127.0.0.1/private','https://user:secret@shop.example'] as $url){$this->postJson('/admin/marketing/free-posts',$this->brief($p,['product_ids'=>[$p->id],'cta_url'=>$url]))->assertUnprocessable();}Http::assertNothingSent();}
 public function test_multi_product_empty_cta_keeps_single_product_default_and_legacy_runs_work(){[$u,$p]=$this->source();config(['marketing.caption_public_origin'=>'https://shop.example']);$s=app(MarketingFreePosts::class);$r=$s->prepare($u,$this->brief($p,['cta_url'=>'']));$this->assertSame('https://shop.example/products/desk-lamp',$r->snapshot['facts']['cta_destination']);$snapshot=$r->snapshot;unset($snapshot['products'],$snapshot['product_ids'],$snapshot['facts']['products'],$snapshot['facts']['custom_cta'],$snapshot['facts']['authorized_percentages']);$r->update(['snapshot'=>$snapshot]);$this->fake();for($i=0;$i<3;$i++)$r=$s->step($u,$r->id);$this->assertSame('completed',$r->status);Http::assertSentCount(2);}
 public function test_multi_product_images_reach_provider_and_all_draft_contexts_without_duplicate_calls(){
  [$u,$p]=$this->source();$q=$p->replicate();$q->title='Office Chair';$q->handle='office-chair';$q->save();$q->images()->create(['path'=>'products/lamp.png','position'=>0]);
  $plan=['angle'=>'Christmas choices','headline'=>'Christmas 30% OFF','cta'=>'Explore Christmas','variants'=>array_fill_keys(['facebook','instagram','tiktok'],"Desk Lamp and Office Chair.\n\nChristmas Sale 30% OFF."),'slides'=>[['headline'=>'Christmas 30% OFF','prompt'=>'Desk Lamp and Office Chair Christmas 30% OFF.']]];
  $image=imagecreatetruecolor(1024,1280);ob_start();imagepng($image);$png=base64_encode(ob_get_clean());imagedestroy($image);
  Http::fake(['api.openai.com/v1/responses'=>Http::response(['status'=>'completed','output'=>[['content'=>[['type'=>'output_text','text'=>json_encode($plan)]]]]]),'api.openai.com/v1/images/edits'=>Http::response(['data'=>[['b64_json'=>$png]]])]);
  $s=app(MarketingFreePosts::class);$r=$s->prepare($u,$this->brief($p,['product_ids'=>[$p->id,$q->id],'notes'=>'Christmas Sale 30% OFF','cta_url'=>'https://shop.example/sale']));for($i=0;$i<4;$i++)$r=$s->step($u,$r->id);
  $this->assertSame('completed',$r->status);Http::assertSentCount(2);Http::assertSent(fn($request)=>str_ends_with($request->url(),'/images/edits')&&count($request['images'])===2&&str_contains($request['prompt'],'Office Chair'));
  foreach($r->post_ids as $id){$doc=MarketingPost::findOrFail($id)->document;$this->assertSame([$p->id,$q->id],$doc['ai_context']['product_ids']);$this->assertSame('https://shop.example/sale',$doc['ai_context']['cta']['url']);$this->assertStringContainsString('https://shop.example/sale',$doc['copy']);$this->assertEmpty($doc['targets']);}
  $this->assertDatabaseCount('marketing_post_attempts',0);
 }
 public function test_multi_product_missing_title_or_invented_discount_is_rejected(){[$u,$p]=$this->source();$s=app(MarketingFreePosts::class);$f=['title'=>$p->title,'products'=>[['title'=>$p->title],['title'=>'Office Chair']],'platforms'=>['facebook'],'slide_count'=>1,'authorized_percentages'=>['30']];$method=new \ReflectionMethod($s,'validatePlan');foreach(['Desk Lamp 30% OFF','Desk Lamp and Office Chair 40% OFF'] as $caption){$plan=['angle'=>'Christmas','headline'=>'Christmas','cta'=>'Explore','variants'=>['facebook'=>$caption],'slides'=>[['headline'=>'Christmas','prompt'=>'Selected products']]];try{$method->invoke($s,$plan,$f);$this->fail('Invalid caption accepted');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertSame(422,$e->getStatusCode());}}Http::assertNothingSent();}
 private function source():array {
  Storage::fake('local');Storage::fake('public');Http::preventStrayRequests();
  $u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]);$this->actingAs($u);
  StoreSetting::create(['key'=>'shop_profile','value'=>['data'=>['shopName'=>'Test Company','email'=>'private@example.test']]]);
  $p=Product::create(['title'=>'Desk Lamp','handle'=>'desk-lamp','status'=>'active','description'=>'White desk lamp. No stand included.','base_price'=>100]);
  $im=imagecreatetruecolor(100,100);ob_start();imagepng($im);$png=ob_get_clean();imagedestroy($im);Storage::disk('public')->put('products/lamp.png',$png);$p->images()->create(['path'=>'products/lamp.png','position'=>0]);
  AiConnection::create(['provider'=>'openai','enabled'=>true,'verified_at'=>now(),'text_model'=>'gpt-5.6-luna','image_model'=>'gpt-image-2','api_key'=>'TEST-ONLY','version'=>1,'models'=>[['id'=>'gpt-5.6-luna','text'=>true],['id'=>'gpt-image-2.5-flare','image'=>true]]]);
  return [$u,$p];
 }
 private function brief(Product $p,array $extra=[]):array{return array_replace(['id'=>(string)Str::uuid(),'product_id'=>$p->id,'type'=>'poster','reference'=>'ai-direction','slides'=>3,'theme'=>'#123e5a','goal'=>'Introduce the product','language'=>'English','tone'=>'Professional','audience'=>'Office teams','notes'=>'Creative marketing scene','evidence'=>'','platforms'=>['Facebook','Instagram','TikTok']],$extra);}
 private function fake(int $slides=1,bool $timeout=false):void {
  $plan=['angle'=>'A calmer workspace','headline'=>'Make room for focus','cta'=>'Explore the product','variants'=>['facebook'=>'Meet Desk Lamp. No stand included.','instagram'=>'Desk Lamp for your everyday desk. No stand included.','tiktok'=>'A new desk idea: Desk Lamp. No stand included.'],'slides'=>array_fill(0,$slides,['headline'=>'Make room for focus','prompt'=>'Create a complete marketing image of the real lamp in a calm office.'])];
  $im=imagecreatetruecolor(1024,1280);ob_start();imagepng($im);$png=base64_encode(ob_get_clean());imagedestroy($im);
  Http::fake(['api.openai.com/v1/responses'=>Http::response(['status'=>'completed','id'=>'response-test','usage'=>['input_tokens'=>100,'output_tokens'=>100],'output'=>[['content'=>[['type'=>'output_text','text'=>json_encode($plan)]]]]]),'api.openai.com/v1/images/edits'=>function()use($timeout,$png){if($timeout)throw new \Illuminate\Http\Client\ConnectionException('uncertain');return Http::response(['data'=>[['b64_json'=>$png]],'usage'=>['input_tokens_details'=>['text_tokens'=>100,'image_tokens'=>100],'output_tokens'=>1000]]);}]);
 }
